export type BoxxyWorkOperation =
  | { upsert: { boxxy_item: BoxxyItemRow } }
  | { upsert: { boxxy_attempt: BoxxyAttemptRow } }
  | { upsert: { boxxy_attempt_session: BoxxyAttemptSessionRow } }
  | { link: { type: 'ran_in'; from: BoxxyAttemptID; to: TelemetrySessionID; confidence: number; evidence: string } }
  | { link: { type: 'produced'; from: BoxxyAttemptID; to: GithubPullRequestID; confidence: number; evidence: string } }
  | { link: { type: 'attempt_of'; from: BoxxyAttemptID; to: BoxxyItemID; confidence: number; evidence: string } };

export function linkRanIn(link: { from: BoxxyAttemptID; to: TelemetrySessionID; confidence: number; evidence: string }): BoxxyWorkOperation {
  return { link: { type: 'ran_in', from: link.from, to: link.to, confidence: link.confidence, evidence: link.evidence } };
}

export function linkProduced(link: { from: BoxxyAttemptID; to: GithubPullRequestID; confidence: number; evidence: string }): BoxxyWorkOperation {
  return { link: { type: 'produced', from: link.from, to: link.to, confidence: link.confidence, evidence: link.evidence } };
}

export function linkAttemptOf(link: { from: BoxxyAttemptID; to: BoxxyItemID; confidence: number; evidence: string }): BoxxyWorkOperation {
  return { link: { type: 'attempt_of', from: link.from, to: link.to, confidence: link.confidence, evidence: link.evidence } };
}
